_FAQS = [
[('Какой кран нужен для разгрузки чиллера?','Подбор требует массы поставки, схемы изготовителя и плана площадки. Холодопроизводительность не заменяет сведения о грузе.'),('Разгрузка включает занос в помещение?','Границу кранового этапа и участие внутренней такелажной бригады согласуют отдельно.'),('Можно заказать замену старого чиллера?','Опишите старый и новый агрегаты раздельно. Сервис должен подтвердить готовность снимаемой машины.'),('Кто готовит схему захвата?','Исполнителю передают применимую инструкцию изготовителя. Техническое решение принимают подготовленные специалисты.')],
[('Производительность компрессора определяет кран?','Нет, нужны масса и габариты фактического исполнения вместе с шасси либо рамой.'),('Можно использовать дышло для подъёма?','Такой способ нельзя назначать без применимого указания изготовителя.'),('Колёсный компрессор обязательно разгружать краном?','Способ выгрузки согласуют по машине, транспорту и документации. Наличие колёс не описывает весь маршрут.'),('Входит ли пуск в аренду крана?','Пуск и обслуживание согласуют с профильным исполнителем отдельным объёмом.')],
[('Можно поднять установку в сборе?','Возможность определяют по инструкции конкретного исполнения. Секционный способ поставки сам по себе не разрешает общий подъём.'),('Нужна масса каждой секции?','Да, общую массу нельзя распределять поровну вместо данных изготовителя.'),('Можно оставить блоки на крыше до монтажа?','Место и допустимость временного размещения подтверждают по проектным условиям с ответственной стороной.'),('Кто предоставляет транспортные элементы?','Комплектность и поставку необходимой оснастки согласуют с поставщиком и исполнителем заранее.')],
[('Достаточно назвать модель станка?','Дополните модель массой и комплектацией фактической поставки, схемой перемещения и размерами.'),('Автокран установит станок внутри цеха?','Сначала проверяют маршрут. Для внутреннего участка может потребоваться отдельная техника и бригада.'),('Кто снимает транспортные фиксаторы?','Порядок подготовки определяют по документации станка с владельцем и сервисом.'),('Входит ли выверка в разгрузку?','Выверка и ввод в работу относятся к отдельно согласованным монтажным операциям.')],
[('Можно подобрать кран по мощности трансформатора?','Нет, нужны масса поставки, исполнение и условия площадки.'),('Схема Trihal подходит любому трансформатору?','Нет, её применимость проверяют по конкретной модели и исполнению.'),('Кто отключает старый трансформатор?','Подготовку электрической части подтверждает профильная эксплуатирующая организация.'),('Разгрузка включает электрические испытания?','Испытания и подключения согласуются отдельным объёмом с профильным исполнителем.')]]
